// The SDK's database upgrades in place on its users' devices: every
// version must migrate to every later one, keeping the queue. Generated by
// `drift_dev make-migrations` (conventions §11.28), then filled in with
// real rows.
import 'package:drift/drift.dart';
import 'package:drift_dev/api/migrations_native.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:tracklite/src/storage/tracklite_database.dart';

import 'generated/schema.dart';
import 'generated/schema_v1.dart' as v1;
import 'generated/schema_v2.dart' as v2;

void main() {
  driftRuntimeOptions.dontWarnAboutMultipleDatabases = true;
  late SchemaVerifier verifier;

  setUpAll(() {
    verifier = SchemaVerifier(GeneratedHelper());
  });

  group('every upgrade path matches the exported schema', () {
    const versions = GeneratedHelper.versions;
    for (final (i, fromVersion) in versions.indexed) {
      group('from $fromVersion', () {
        for (final toVersion in versions.skip(i + 1)) {
          test('to $toVersion', () async {
            final schema = await verifier.schemaAt(fromVersion);
            final db = TrackLiteDatabase(schema.newConnection());
            await verifier.migrateAndValidate(db, toVersion);
            await db.close();
          });
        }
      });
    }
  });

  // The upgrade that matters most: a device with events still waiting must
  // keep every one of them, and its identity and totals.
  test(
    'v1 → v2 keeps the waiting events, the identity and the totals',
    () async {
      const pending = v1.EventsData(
        seq: 1,
        id: 'e1',
        name: 'purchase',
        timestamp: '2026-11-03T09:41:00.000Z',
        userId: 'user_123',
        anonymousId: 'anon',
        properties: '{"price":20}',
        status: 'pending',
        attempts: 0,
      );
      const failed = v1.EventsData(
        seq: 2,
        id: 'e2',
        name: 'tap',
        timestamp: '2026-11-03T09:42:00.000Z',
        anonymousId: 'anon',
        properties: '{}',
        status: 'failed',
        attempts: 5,
        lastError: 'server error 500',
      );
      const meta = [
        v1.MetaData(name: 'anonymous_id', value: 'anon'),
        v1.MetaData(name: 'tracked_total', value: '2'),
      ];

      await verifier.testWithDataIntegrity(
        oldVersion: 1,
        newVersion: 2,
        createOld: v1.DatabaseAtV1.new,
        createNew: v2.DatabaseAtV2.new,
        openTestedDatabase: TrackLiteDatabase.new,
        createItems: (batch, oldDb) {
          batch
            ..insertAll(oldDb.events, [pending, failed])
            ..insertAll(oldDb.meta, meta);
        },
        validateItems: (newDb) async {
          expect(await newDb.select(newDb.events).get(), [
            v2.EventsData.fromJson(pending.toJson()),
            v2.EventsData.fromJson(failed.toJson()),
          ]);
          expect(await newDb.select(newDb.meta).get(), [
            for (final row in meta) v2.MetaData.fromJson(row.toJson()),
          ]);
          expect(await newDb.select(newDb.uploads).get(), isEmpty);
        },
      );
    },
  );
}
